        s.frame = union([part(p) for p in s.fixed])
        s.sol = {k: union([part(p) for p in v["parts"]]) for k, v in s.mob.items()}
        s.ax = {k: v["axis"] for k, v in s.mob.items()}
        s.cc = d["case_centre"]; s.meshes = d["meshes"]
    def speeds(s):
        sp = {"barrel": Fr(-1, s.hours)}  # ccw positive, rev/h
        ch = True; ok = True
        while ch:
            ch = False
            for m in s.meshes:
                a, b, za, zb = m["driver"], m["driven"], m["driver_teeth"], m["driven_teeth"]
                for (p, q, zp, zq) in ((a, b, za, zb), (b, a, zb, za)):
                    if p in sp:
                        v = -sp[p] * zp / zq
                        if q not in sp: sp[q] = v; ch = True
                        elif sp[q] != v: ok = False
        return sp, ok

def c2(M):
    ok = True
    names = list(M.sol)
    for a in names:
        v = K.ivol(M.frame, M.sol[a])
        if v > TOL: print("  C2 frame/", a, v); ok = False
    for a, b in itertools.combinations(names, 2):
        v = K.ivol(M.sol[a], M.sol[b])
        if v > TOL: print("  C2", a, b, v); ok = False
    for a, b in itertools.combinations(M.fixed, 2):
        v = K.ivol(part(a), part(b))
        if v > TOL: print("  C2 fixed", a, b, v); ok = False
    for k, v in M.mob.items():
        for a, b in itertools.combinations(v["parts"], 2):
            w = K.ivol(part(a), part(b))
            if w > TOL: print("  C2 mobile parts", a, b, w); ok = False
    # connectivity
    seen = {M.fixed[0]}; ch = True
    while ch:
        ch = False
        for a in M.fixed:
            if a in seen: continue
            if any(K.min_distance(part(a), part(b), 0.05) <= 0.01 for b in seen): seen.add(a); ch = True
    if len(seen) != len(M.fixed): print("  C2 frame not joined", set(M.fixed) - seen); ok = False
    return ok

def free(M):
