        while ch:
            ch = False
            for a in ps:
                if a not in seen and any(K.min_distance(part(a), part(b), 0.05) <= 0.02 for b in seen): seen.add(a); ch = True
        if len(seen) != len(ps): print("  seated chain", k); ok = False
    return ok

def mesh_test(M, m, shift=0.0, verbose=True):
