            ok &= np.abs(path[:, 3] - [0, 0, 0, 1]).max() < 1e-6 and np.abs(path[-1] - np.eye(4)).max() < 1e-6
            v = K.verts(pm); w = np.einsum("nij,vj->nvi", R, v) + path[:, None, :3, 3]
            if np.linalg.norm(np.diff(w, axis=0), axis=2).max() > 0.2: ok = False; print("   step too long", n)
            b0 = K.apply(pm, path[0]).bounding_box()
            if all(b0[i] < grown[i + 3] and grown[i] < b0[i + 3] for i in range(3)): ok = False; print("   start inside box", n)
            worst = 0
            for Tm in path:
                q = K.apply(pm, Tm)
                for o in placed:
                    worst = max(worst, K.ivol(q, part(o)))
            if worst > TOL: ok = False; print("   collides", n, worst)
        print("  assembly %-22s %s" % (n, "installed" if ok else "NOT installed"), flush=True)
        good += bool(ok); placed.append(n)
    return good == len(names)

if __name__ == "__main__":
