           "train": lambda: train(M, fn), "train5": lambda: train(M, fn, (0.03, -0.03)),
           "print": lambda: printable(M.fixed + [p for k, v in M.mob.items() if k != "barrel" for p in v["parts"]])}
    for w in which:
        t = time.time(); res[w] = fns[w](); print("%s: %s (%.0fs)" % (w, "PASS" if res[w] else "FAIL", time.time() - t), flush=True)
    print(res)
